import { createHash } from "node:crypto";
import { getObject, KEYS } from "./store.mjs";

// did:webvh controllers. A Space's controller may be a did:webvh whose log
// (did.jsonl) the server resolves to the account document as it stands
// NOW, and authorizes against: an invocation verifies only if its key is
// listed in that document (the current-key-set rule), so revoking a key is
// one log entry. The did:webvh driver (@interop/did-method-webvh) is handed
// in by the function that bundles it; this module holds what is shared:
// where a log comes from, the limits on fetching it, the cache, and the
// document checks.
//
// Two fetchers, one verifier. A DID whose domain is this deployment's
// identity domain and whose single path segment is a Space id names a log
// published in that Space's world-readable `id` collection; it is read
// from the bucket, which sees a write the moment it lands and depends on no
// public-read policy. Any other DID's log is fetched over HTTPS from the
// location the DID encodes, with a size cap and a timeout.

const ID_DOMAIN = process.env.ID_DOMAIN ?? "";
const CACHE_MS = Number(process.env.WEBVH_CACHE_SECONDS ?? "30") * 1000;
const FETCH_TIMEOUT_MS = Number(process.env.WEBVH_FETCH_TIMEOUT_MS ?? "3000");
const MAX_LOG_BYTES = Number(process.env.WEBVH_MAX_LOG_BYTES ?? String(1024 * 1024));

export const LOG_COLLECTION = "id";
export const LOG_RESOURCE = "did.jsonl";

export const isWebvhDid = (did) => typeof did === "string" && did.startsWith("did:webvh:");

// was-client's `deriveSpaceId`: the unpadded base64url of SHA-256 over the
// controller DID. An unlock Space's id, derived by the client from its own
// controller, so the server can check the claim without a lookup.
export function deriveSpaceId(did) {
  return createHash("sha256").update(did, "utf8").digest("base64url");
}

// The DID's location parts: the domain the log is served from and the path
// segments below it (the DID encodes a port as %3A).
export function locationOf(did) {
  const [, , , domain, ...paths] = did.split("#")[0].split(":");
  if (!domain) {
    throw new Error("Not a did:webvh identifier.");
  }
  return { domain: decodeURIComponent(domain), paths };
}

// Where to read a log from: a Space on this server, or a URL.
export function logSource(did) {
  const { domain, paths } = locationOf(did);
  if (ID_DOMAIN && domain === ID_DOMAIN && paths.length === 1) {
    return { spaceId: paths[0] };
  }
  return { url: `https://${domain}/${paths.map(encodeURIComponent).join("/")}/${LOG_RESOURCE}` };
}

async function readLocalLog(spaceId) {
  const object = await getObject(spaceId, KEYS.resource(LOG_COLLECTION, LOG_RESOURCE));
  return object === null ? null : object.body.toString("utf8");
}

async function fetchLog(url, fetchImpl) {
  const response = await fetchImpl(url, { signal: AbortSignal.timeout(FETCH_TIMEOUT_MS), redirect: "follow" });
  if (!response.ok) {
    return null;
  }
  const length = Number(response.headers?.get?.("content-length") ?? 0);
  if (length > MAX_LOG_BYTES) {
    throw new Error(`DID log at ${url} exceeds ${MAX_LOG_BYTES} bytes.`);
  }
  const text = await response.text();
  if (Buffer.byteLength(text, "utf8") > MAX_LOG_BYTES) {
    throw new Error(`DID log at ${url} exceeds ${MAX_LOG_BYTES} bytes.`);
  }
  return text;
}

const cache = new Map();

// Resolves a did:webvh to its current document, or null when no log is
// found. Throws when the log is found but does not resolve to the DID (a
// log at the wrong location, a broken chain, a deactivated DID). `driver`
// is the did:webvh package; `fetch` may be replaced for tests.
export async function resolveWebvhDocument(did, { driver, fetch: fetchImpl = globalThis.fetch, now = Date.now } = {}) {
  const cached = cache.get(did);
  if (cached && cached.expires > now()) {
    return cached.doc;
  }
  const source = logSource(did);
  const text = source.spaceId !== undefined ? await readLocalLog(source.spaceId) : await fetchLog(source.url, fetchImpl);
  if (text === null) {
    return null;
  }
  const { did: resolved, doc, meta } = await driver.resolveDIDFromLog(driver.readLogFromString(text));
  if (resolved !== did || !doc) {
    throw new Error(`The log for ${did} resolves to ${resolved ?? "nothing"}.`);
  }
  if (meta?.deactivated) {
    throw new Error(`${did} is deactivated.`);
  }
  cache.set(did, { doc, expires: now() + CACHE_MS });
  return doc;
}

export function clearWebvhCache() {
  cache.clear();
}

// An id as the document writes it, absolute: a relative `#fragment` is
// relative to the document's own id.
const absolute = (doc, id) => (typeof id === "string" && id.startsWith("#") ? `${doc.id}${id}` : id);

// The ids a verification relationship lists (entries are ids or embedded
// methods), absolute.
export function relationIds(doc, relation) {
  return (doc?.[relation] ?? [])
    .map((entry) => absolute(doc, typeof entry === "string" ? entry : entry?.id))
    .filter(Boolean);
}

// The verification method `keyId` names, when the document lists it under
// `relation`; null otherwise.
export function verificationMethodFor(doc, keyId, relation) {
  if (!relationIds(doc, relation).includes(keyId)) {
    return null;
  }
  const embedded = (doc[relation] ?? []).find((entry) => typeof entry === "object" && absolute(doc, entry?.id) === keyId);
  return embedded ?? (doc.verificationMethod ?? []).find((method) => absolute(doc, method?.id) === keyId) ?? null;
}

// Whether a did:key's signing key is one the document authorizes to invoke:
// the promotion rule. A key that can invoke as the did:webvh may move a
// Space it controls as a did:key onto the did:webvh.
export function invokerKeyListed(doc, didKey) {
  const multibase = didKey.split("#")[0].slice("did:key:".length);
  return relationIds(doc, "capabilityInvocation").some((id) => {
    const method = verificationMethodFor(doc, id, "capabilityInvocation");
    return method?.publicKeyMultibase === multibase;
  });
}
